import{_ as n,o as e,c as t,aj as r}from"./chunks/framework.BdtAaXf2.js";const o="/assets/image-20260306093254958.CKHr4Tqg.png",s="/assets/image-20260306092724611.4S8e2Y-d.png",p="/assets/image-20260306092840107.DwGtzHKk.png",i="/assets/image-20260306092932466.BFKNzrDa.png",m="/assets/image-20260306093050779.k10AWfnE.png",l="/assets/image-20260306093206391.BIK4A__W.png",d="/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg",k=JSON.parse('{"title":"我的HarmonyOS 应用开发知识库又更新了","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/我的HarmonyOS 应用开发知识库又更新了20260306/我的HarmonyOS 应用开发知识库又更新了20260306.md","filePath":"鸿蒙开发技巧/我的HarmonyOS 应用开发知识库又更新了20260306/我的HarmonyOS 应用开发知识库又更新了20260306.md","lastUpdated":1772761226000,"__rawMarkdown":"# 我的HarmonyOS 应用开发知识库又更新了\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：[https://blog.zbztb.cn/](https://blog.zbztb.cn/)\\n>\\n> **2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。**\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n## 前言\\n\\n2025年利用腾讯的IMA搭建了对其华为开发者联盟开发者文档的知识库，受到了不少伙伴的好评。\\n\\n目前已经有将近700用户深度使用。\\n\\n![](assets/image-20260306093254958.png)\\n\\n其中日常开发、HarmonyOS 高级证书辅导等场景也很受伙伴的欢迎。\\n\\n昨天抽空同步了截至2026年3月6日的开发文档，对应最新API22，目前最新的特性和API都可以在知识库中进行使用了。\\n\\n![](assets/image-20260306092724611.png)\\n\\n## 使用方式\\n\\n目前支持3种使用方式\\n\\n### 1. 安装ima客户端\\n\\n这个是我推荐的，使用体验最好\\n\\n> https://ima.qq.com/download/?rmWeb=1&webFrom=10000476&channel=10000476&urlid=61&bd_vid=16574119226102129516\\n\\n![](assets/image-20260306092840107.png)\\n\\n### 2. 小程序中直接使用\\n\\n电脑端和手机端都可以打开**ima**小程序\\n\\n![](assets/image-20260306092932466.png)\\n\\n### 3. 公众号内使用\\n\\n我的公众号 《HarmonyOS 万少》中也是接入了 这个知识库，关注后点击可以直接跳转使用（也是跳转到小程序）\\n\\n![](assets/image-20260306093050779.png)\\n\\n\\n\\n\\n\\n## 免费加入知识库\\n\\n然后你需要加入这个知识库就可以使用了。\\n\\n1. 点击链接\\n\\n   > 【ima知识库】鸿蒙应用知识库HarmonyOS6 https://ima.qq.com/wiki/?shareId=b0d462ae618a0fefb5b714565cad3dd4a60411a435d5f81db51670ffb2ff3ad7\\n\\n2. 或者扫码加入\\n\\n![](assets/image-20260306093206391.png)\\n\\n## 最后\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![](assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg)"}'),c={name:"鸿蒙开发技巧/我的HarmonyOS 应用开发知识库又更新了20260306/我的HarmonyOS 应用开发知识库又更新了20260306.md"};function _(h,a,b,g,f,q){return e(),t("div",null,[...a[0]||(a[0]=[r("",28)])])}const A=n(c,[["render",_]]);export{k as __pageData,A as default};
